const rawTexts = (input.chatInput || input.question || input.text || '').trim(); 
const rawText = rawTexts.toLowerCase(); 
const sessionId = input.sessionId || 'sess-' + Math.random().toString(36).slice(2,10); 
const { franc } = require('franc'); // <-- note the destructuring 
const langs = require('langs'); 
// Get the text from input JSON 
// Detect the language (ISO 639-3 code) 
const langCode = franc(rawText); 
// Convert ISO code to readable language name 
