// this part is for connecting with the UI

const message = $input.all()[0].json;

// ✅ Extract data from message.body
const body = message.body || {};
console.log("📦 Full request body:", JSON.stringify(body));

// Extract the query from inside body
let query = body.chatInput || body.message || body.query || body.text || '';
console.log("🧪 Raw query:", query);

// ✅ Force to string if necessary
if (typeof query !== 'string') {
  try {
    query = JSON.stringify(query);
  } catch (err) {
    query = '';
  }
}

// ✅ Apply trim and lowercase
query = query.trim().toLowerCase();

console.log("✅ Cleaned query:", query);

const { franc } = require('franc'); // <-- note the destructuring 
const langs = require('langs'); 
// Get the text from input JSON 
// Detect the language (ISO 639-3 code) 
const langCode = franc(query); 
// Convert ISO code to readable language name 
let langName; 
try {
  langName = langs.where("3", langCode).name; 
} catch {
  langName = "Unknown"; 
} 

// Session ID
const sessionId = body.sessionId || Math.random().toString(36).substring(2) + Date.now().toString(36);

return {
  json: {
    originalMessage: body,
    cleanedQuestion: query,
    language_code: langCode, 
    language_name: langName, 
    sessionId,
    timestamp: new Date().toISOString()
  }
};

